// Reference sheets, once per film — for the cast AND for the hero objects.
//
// Tiers, decided by how often a name appears across the film's scenes
// (Load Scene Cast): a LEAD gets a TURNAROUND sheet (front, both profiles,
// back — the back of a coat and the side of a face were never seen by the
// model before, so every shot from behind invented them); a RECURRING
// character (two or more scenes) gets the single portrait the cast sheet
// port shipped with; a one-scene extra gets no sheet — nothing to be
// consistent WITH, and a faceless extra is also what the people filter
// prefers. Hero objects (the bible's `objects`: a car, a machine, a ship)
// get a three-view product sheet, because on the race film the CAR was the
// character that drifted.
//
// The producer's own photo, when the film has one, is the base of the
// protagonist's sheet: the sheet is drawn FROM it, so the real face and
// outfit reach every scene instead of only the hook.
//
// Free on the Ultra plan, one Flow call per sheet, once per film: the ids
// are stored on the project, so a later pass generates nothing — except an
// upgrade, when a character that had a portrait now qualifies for a
// turnaround (films made before this existed).
const proj = $('IMG Load Project').first().json;
const f = proj.fields || {};
let opts = {};
try { opts = JSON.parse(f['Editing Options'] || '{}') || {}; } catch (e) { opts = {}; }
try { if ($('Save User Ref Id').isExecuted) { const m = $('Save User Ref Id').first().json.media_id; if (m) opts.refImageMediaId = String(m); } } catch (e) {}
const castRefs = (opts.castRefs && typeof opts.castRefs === 'object') ? opts.castRefs : {};
const castSheets = (opts.castSheets && typeof opts.castSheets === 'object') ? opts.castSheets : {};
const objectRefs = (opts.objectRefs && typeof opts.objectRefs === 'object') ? opts.objectRefs : {};
let bible = {};
try { bible = JSON.parse(f['Story Bible'] || '{}') || {}; } catch (e) { bible = {}; }
const chars = Array.isArray(bible.characters) ? bible.characters : [];
const objs = Array.isArray(bible.objects) ? bible.objects : [];
const rb = $('Receive Batch Input').first().json;
const aspect = rb.Aspect_Ratio === '9:16' ? '9:16' : '16:9';
const MODEL = 'nano-banana-2';

const norm = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Appearances per name. Tags first (exact bible names chosen by the
// segmenter); a scene without tags is matched on Prompt Vizual by full
// name, or by the given name where it is unique among the cast.
let scenes = [];
try { scenes = $('Load Scene Cast').all().map((it) => it.json).filter((s) => s && s.id); } catch (e) { scenes = []; }
const givens = chars.map((c) => norm(String((c || {}).name || '').split(/\s+/)[0] || ''));
const count = (name, prefix, i) => {
  const full = norm(name), given = norm(name.split(/\s+/)[0] || '');
  const keys = givens.filter((g) => g && g === given).length > 1 || prefix !== 'char:' ? [full] : [full, given];
  let n = 0;
  for (const s of scenes) {
    const tags = (Array.isArray(s.tags) ? s.tags : []).map(String);
    const tagged = tags.filter((t) => t.startsWith(prefix));
    if (tagged.length) { if (tagged.some((t) => norm(t.slice(prefix.length)) === full)) n++; continue; }
    const text = ' ' + norm(s.visual_prompt || '') + ' ';
    if (keys.some((k) => k.length > 2 && new RegExp('\\b' + esc(k) + '\\b').test(text))) n++;
  }
  return n;
};
const total = scenes.length;
const leadMin = Math.max(3, Math.ceil(total * 0.1));
const protagonist = (() => {
  const byRole = chars.find((c) => /protagonist|lead|main|hero/i.test(String((c || {}).role || '')));
  return String(((byRole || chars[0]) || {}).name || '');
})();
const userRefId = String(opts.refImageMediaId || '');

const work = [];
const tiers = {};
chars.forEach((c, i) => {
  const name = String((c || {}).name || '').trim();
  const desc = String((c || {}).visual_description || '').trim();
  if (!name || !desc) return;
  const n = total ? count(name, 'char:', i) : 2; // no scene list at all: behave like the old port
  const kind = n >= leadMin || (norm(name) === norm(protagonist) && n >= 2) ? 'turnaround' : (n >= 2 ? 'portrait' : 'none');
  tiers[name] = { appearances: n, kind: kind };
  if (kind === 'none') return;
  const have = castRefs[name] ? String((castSheets[name] || {}).kind || 'portrait') : '';
  if (have === kind || (have === 'turnaround')) return; // already has this or better
  if (work.length >= 6) return;
  const isProt = norm(name) === norm(protagonist) && !!userRefId;
  const base = kind === 'turnaround'
    ? 'Character reference sheet of ONE person on a plain neutral grey studio backdrop: four full-body views standing side by side in one row — front view, left profile, back view, right profile — identical outfit, hair and build in all four, relaxed natural standing pose, even soft studio lighting, no text, no labels, no grid lines, no props, nothing else in frame: '
    : 'Character reference portrait of ONE person, centred, front three-quarter view, plain neutral studio backdrop, even soft lighting, no props, no text, no collage: ';
  const body = {
    email: rb.Flow_Email || 'fermafabiz@gmail.com',
    model: MODEL,
    prompt: (isProt ? 'The reference image is the producer\'s own photo of this person and is GROUND TRUTH: build the sheet FROM it — exactly that face, hair, body and outfit, in every view. ' : '') +
      base + desc + ' If the description offers alternatives for different eras or scenes, use the FIRST one only — one person, one outfit, one age. Photorealistic, natural skin texture, sharp focus.',
    aspectRatio: kind === 'turnaround' ? '16:9' : aspect,
    count: 1,
    captchaRetry: 1,
  };
  if (isProt) body.reference_1 = userRefId;
  work.push({ kind: 'cast', sheet: kind, name: name, requestBody: body });
});
objs.forEach((o) => {
  const name = String((o || {}).name || '').trim();
  const desc = String((o || {}).visual_description || '').trim();
  if (!name || !desc || objectRefs[name]) return;
  const n = total ? count(name, 'obj:') : 2;
  tiers[name] = { appearances: n, kind: n >= 2 ? 'object' : 'none' };
  if (n < 2 || work.filter((w) => w.kind === 'object').length >= 3) return;
  work.push({ kind: 'object', sheet: 'object', name: name, requestBody: {
    email: rb.Flow_Email || 'fermafabiz@gmail.com', model: MODEL,
    prompt: 'Product reference sheet of ONE object on a plain neutral grey studio backdrop: three views side by side in one row — front three-quarter view, side profile, rear three-quarter view — identical design, colours, markings, materials and proportions in all three, even soft studio lighting, no text, no labels, no people, nothing else in frame: ' + desc + ' Photorealistic, sharp focus.',
    aspectRatio: '16:9', count: 1, captchaRetry: 1,
  } });
});
console.log('SHEET PLAN (' + total + ' scenes, lead from ' + leadMin + '): ' + JSON.stringify(tiers) + ' -> making ' + work.map((w) => w.sheet + ':' + w.name).join(', ') || 'nothing');
// NEVER return zero items: everything downstream of this node is the rest of
// the batch, and an empty output would end the pass silently.
if (!work.length) return [{ json: { skip: true } }];
return work.map((w) => ({ json: w }));

// Pair each generated sheet with what it was made for, and hand the maps on
// as ONE item. The HTTP node is onError: continueRegularOutput, so a refused
// or failed sheet arrives here as an item without media — that name simply
// has no sheet and falls back to text + the n-1 chain. Order is 1:1 with
// Cast Sheet Prep's items.
//
// Two maps per kind: `castRefs` {name: id} is what the generators attach;
// `castSheets` {name: {id, url, kind}} carries the signed fifeUrl the
// Consistency Judge looks at (it expires in hours — the judge skips a sheet
// it can no longer fetch) and the tier, so an upgrade from portrait to
// turnaround can be recognised on a later pass.
const prep = $('Cast Sheet Prep').all();
const outs = $input.all();
const cast = {}, sheets = {}, objects = {}, failed = [];
outs.forEach((it, i) => {
  const p = ((prep[i] || {}).json) || {};
  const name = String(p.name || '');
  let gi = {};
  try { gi = ((((it.json || {}).media || [])[0] || {}).image || {}).generatedImage || {}; } catch (e) { gi = {}; }
  const id = String(gi.mediaGenerationId || ''), url = String(gi.fifeUrl || '');
  if (!name || !id) { if (name) failed.push(name); return; }
  if (p.kind === 'object') objects[name] = id;
  else { cast[name] = id; sheets[name] = { id: id, url: url, kind: p.sheet || 'portrait' }; }
});
for (const n of failed) console.log('SHEET FAILED: ' + n + ' — falls back to text and the n-1 chain');
console.log('SHEETS MADE: cast ' + (Object.keys(cast).join(', ') || 'none') + '; objects ' + (Object.keys(objects).join(', ') || 'none'));
let opts = {};
try { opts = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {}; } catch (e) { opts = {}; }
const merge = (a, b) => Object.assign({}, (a && typeof a === 'object') ? a : {}, b);
return [{ json: {
  castRefs: merge(opts.castRefs, cast),
  castSheets: merge(opts.castSheets, sheets),
  objectRefs: merge(opts.objectRefs, objects),
  made: Object.keys(cast).length + Object.keys(objects).length,
} }];

// One establishing plate per bible location, once per film.
//
// The location's visual_description is pasted into every prompt set there,
// and prose keeps the palette and the materials but not the GEOMETRY: the
// same warehouse came back with a different floor plan in every scene. A
// plate is a wide, empty, evenly lit picture of the place that every scene
// there is anchored to — same architecture, same layout, same landmarks —
// while the text still sets the hour, the weather and the framing. Neutral
// overcast light on purpose: a dawn plate would drag a night scene's light
// the wrong way. Free on the Ultra plan; ids stored on the project as
// `locationRefs`, so a later pass makes nothing.
const proj = $('IMG Load Project').first().json;
const f = proj.fields || {};
let opts = {};
try { opts = JSON.parse(f['Editing Options'] || '{}') || {}; } catch (e) { opts = {}; }
const have = (opts.locationRefs && typeof opts.locationRefs === 'object') ? opts.locationRefs : {};
let bible = {};
try { bible = JSON.parse(f['Story Bible'] || '{}') || {}; } catch (e) { bible = {}; }
const locs = Array.isArray(bible.locations) ? bible.locations : [];
const rb = $('Receive Batch Input').first().json;
const aspect = rb.Aspect_Ratio === '9:16' ? '9:16' : '16:9';
const work = [];
for (const l of locs) {
  const name = String((l || {}).name || '').trim();
  const desc = String((l || {}).visual_description || '').trim();
  if (!name || !desc || have[name]) continue;
  if (work.length >= 6) break;
  work.push({ name: name, requestBody: {
    email: rb.Flow_Email || 'fermafabiz@gmail.com',
    model: 'nano-banana-2',
    prompt: 'Establishing reference plate of ONE location, wide shot at eye level, completely empty of people and vehicles, soft neutral overcast daylight without strong shadows so every part of the place reads clearly, photorealistic, sharp focus, no text, no labels: ' + desc + ' Show the whole layout in one frame — what stands at the centre, on the left, on the right and in the background — and the materials, colours and landmarks that identify this exact place.',
    aspectRatio: aspect, count: 1, captchaRetry: 1,
  } });
}
if (!work.length) return [{ json: { skip: true } }];
return work.map((w) => ({ json: w }));

// Pair each plate with its location; failures fall back to text only.
const prep = $('Set Plate Prep').all();
const outs = $input.all();
const refs = {}, plates = {};
outs.forEach((it, i) => {
  const name = String((((prep[i] || {}).json) || {}).name || '');
  let gi = {};
  try { gi = ((((it.json || {}).media || [])[0] || {}).image || {}).generatedImage || {}; } catch (e) { gi = {}; }
  if (name && gi.mediaGenerationId) { refs[name] = String(gi.mediaGenerationId); plates[name] = { id: String(gi.mediaGenerationId), url: String(gi.fifeUrl || '') }; }
  else if (name) console.log('SET PLATE FAILED: ' + name + ' — scenes there fall back to text');
});
console.log('SET PLATES MADE: ' + (Object.keys(refs).join(', ') || 'none'));
let opts = {};
try { opts = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {}; } catch (e) { opts = {}; }
const merge = (a, b) => Object.assign({}, (a && typeof a === 'object') ? a : {}, b);
return [{ json: { locationRefs: merge(opts.locationRefs, refs), locationPlates: merge(opts.locationPlates, plates), made: Object.keys(refs).length } }];

const f = $json.fields || {};
const prompt = f['Imagine First Frame'] || f['Prompt Vizual'] || '';
if (!prompt) throw new Error('Scene ' + $json.id + ' has no image prompt.');
const rb = $('Receive Batch Input').first().json;
const aspect = rb.Aspect_Ratio === '9:16' ? '9:16' : '16:9';
// Images are generated ON Google Flow (useapi POST /google-flow/images); the
// response carries the fifeUrl the ingest re-hosts and the mediaGenerationId
// Submit Video needs. One model string, here, in the gate's regen and in
// Claude Scripting's IR Build Request — the three must agree.
const MODEL = 'nano-banana-2';

// The project as read at pass start, plus whatever THIS pass stored after that
// read (the user photo id, the cast sheets, the set plates).
const projF = ($('IMG Load Project').first().json.fields || {});
let opts = {}; try { opts = JSON.parse(projF['Editing Options'] || '{}') || {}; } catch (e) { opts = {}; }
let bible = {}; try { bible = JSON.parse(projF['Story Bible'] || '{}') || {}; } catch (e) { bible = {}; }
try { if ($('Save User Ref Id').isExecuted) { const m = $('Save User Ref Id').first().json.media_id; if (m) opts.refImageMediaId = String(m); } } catch (e) {}
try { if ($('Save Cast Refs').isExecuted) { const j = $('Save Cast Refs').first().json; if (j.cast_refs) opts.castRefs = j.cast_refs; if (j.cast_sheets) opts.castSheets = j.cast_sheets; if (j.object_refs) opts.objectRefs = j.object_refs; } } catch (e) {}
try { if ($('Save Set Plates').isExecuted) { const j = $('Save Set Plates').first().json; if (j.location_refs) opts.locationRefs = j.location_refs; } } catch (e) {}
const userRefId = String(opts.refImageMediaId || '');
const isFirstScene = Number(f['Ordine Scenă']) === 1;

// n-1 chain: the previous scene's generated image, BY ITS FLOW MEDIA ID, read
// from the previous run of Decode Scene Image (run data survives Wait
// suspensions, unlike static data in test executions — execution 661).
let prevId = '';
let prevPrompt = '';
try {
  if ($runIndex > 0) {
    const prev = $('Decode Scene Image').all(0, $runIndex - 1);
    if (prev && prev[0] && prev[0].json && prev[0].json.mediaId) prevId = prev[0].json.mediaId;
    const prevReq = $('Build Image Request').all(0, $runIndex - 1);
    if (prevReq && prevReq[0] && prevReq[0].json) prevPrompt = prevReq[0].json.rawPrompt || '';
  }
} catch (e) { prevId = ''; }
// Similarity guard, unchanged: near-identical consecutive prompts keep the
// subject consistent by text alone; the reference would collapse the
// composition (the Porsche films). Sheets and plates are NOT subject to it —
// they carry identity and place, not layout.
const wordSet = (s) => new Set(String(s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(w => w.length > 3));
let promptSim = 0;
if (prevPrompt) {
  const A = wordSet(prompt), B = wordSet(prevPrompt);
  if (A.size && B.size) { let hit = 0; for (const w of A) if (B.has(w)) hit++; promptSim = hit / Math.max(A.size, B.size); }
}
if (promptSim > 0.55) prevId = '';
const afterRefusal = /AUTO-REWRITE/.test(String(f['Observații Scenă'] || ''));

// A consistency re-roll (Judge Verdict sent this scene back) tightens the
// wording and carries the judge's reasons; counted per scene per pass.
const sd = $getWorkflowStaticData('global');
sd.consistencyRerolls = sd.consistencyRerolls || {};
sd.consistencyNotes = sd.consistencyNotes || {};
const strict = (sd.consistencyRerolls[$json.id] || 0) > 0;
const strictNotes = strict ? String(sd.consistencyNotes[$json.id] || '') : '';
// ---------------------------------------------------------------------------
// REFERENCE ASSEMBLY — shared word for word by Build Image Request (batch),
// Evaluate Image Approval (the gate's regen) and IR Build Request (the site's
// regen). Change one, change all three: a re-rolled picture built from
// different references than its neighbours is the drift this exists to stop.
//
// Consistency comes from PICTURES the model is anchored to, never from prose:
//   - cast sheets   (castRefs / castSheets)   one per character, turnaround or portrait
//   - object sheets (objectRefs)              one per hero object (a car, a machine)
//   - set plates    (locationRefs)            one per bible location, wide, empty
//   - the producer's own photo                ground truth on scene 1
//   - the previous frame                      LAST, palette only
// Who and where come from the scene's own tags (`char:`, `obj:`, `loc:`),
// written by the segmenter; films made before the tags existed fall back to
// name matching on Prompt Vizual, exactly as the cast sheet did.
const CONS = (function () {
  const norm = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const tagsOf = (f) => (Array.isArray(f['Tag-uri Scenă']) ? f['Tag-uri Scenă'] : []).map((t) => String(t));
  const tagged = (f, prefix) => tagsOf(f).filter((t) => t.startsWith(prefix)).map((t) => t.slice(prefix.length).trim()).filter(Boolean);
  const mentions = (text, name, allGivens) => {
    const full = norm(name);
    const given = norm(name.split(/\s+/)[0] || '');
    const keys = (allGivens || []).filter((g) => g && g === given).length > 1 ? [full] : [full, given];
    return keys.some((k) => k.length > 2 && new RegExp('\\b' + esc(k) + '\\b').test(text));
  };
  // Which bible entries are IN this scene: tags first (exact names the
  // segmenter chose from the bible), name matching second.
  function present(f, entries, prefix, textFields) {
    const names = entries.map((e) => String((e || {}).name || '').trim()).filter(Boolean);
    const fromTags = tagged(f, prefix).map(norm);
    if (fromTags.length) return names.filter((n) => fromTags.includes(norm(n)));
    const text = ' ' + norm(textFields.map((k) => f[k] || '').join(' ')) + ' ';
    const givens = names.map((n) => norm(n.split(/\s+/)[0] || ''));
    return names.filter((n) => mentions(text, n, givens));
  }
  function plan(a) {
    // a: { f, opts, bible, prompt, prevId, userRefId, isFirstScene, afterRefusal, strict, strictNotes }
    const opts = a.opts || {}, bible = a.bible || {}, f = a.f || {};
    const castRefs = (opts.castRefs && typeof opts.castRefs === 'object') ? opts.castRefs : {};
    const castSheets = (opts.castSheets && typeof opts.castSheets === 'object') ? opts.castSheets : {};
    const objectRefs = (opts.objectRefs && typeof opts.objectRefs === 'object') ? opts.objectRefs : {};
    const locationRefs = (opts.locationRefs && typeof opts.locationRefs === 'object') ? opts.locationRefs : {};
    const chars = Array.isArray(bible.characters) ? bible.characters : [];
    const objs = Array.isArray(bible.objects) ? bible.objects : [];
    const locs = Array.isArray(bible.locations) ? bible.locations : [];
    const refs = []; // {id, role, name}
    const used = { cast: [], objects: [], location: '', user: false, palette: false };
    if (a.afterRefusal) {
      // A refusal is likeliest about a face; nothing is attached, the prompt
      // rewrite alone carries the retry. Same rule as before the sheets.
      return { refs, used, prompt: a.prompt };
    }
    const protagonist = (() => {
      const byRole = chars.find((c) => /protagonist|lead|main|hero/i.test(String((c || {}).role || '')));
      return String(((byRole || chars[0]) || {}).name || '');
    })();
    if (a.isFirstScene && a.userRefId) { refs.push({ id: a.userRefId, role: 'user', name: protagonist }); used.user = true; }
    // Cast: leads (turnaround sheets) first, then portraits; two at most —
    // a third sheet crowds the composition (measured on the cast sheet port).
    const inScene = present(f, chars, 'char:', ['Prompt Vizual']).filter((n) => castRefs[n]);
    inScene.sort((x, y) => ((castSheets[y] || {}).kind === 'turnaround') - ((castSheets[x] || {}).kind === 'turnaround'));
    for (const n of inScene) {
      if (used.user && norm(n) === norm(protagonist)) continue; // the photo is truer than the sheet
      if (used.cast.length >= 2) break;
      refs.push({ id: castRefs[n], role: 'cast', name: n }); used.cast.push(n);
    }
    const objsIn = present(f, objs, 'obj:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => objectRefs[n]);
    for (const n of objsIn) { if (used.objects.length >= 1) break; refs.push({ id: objectRefs[n], role: 'object', name: n }); used.objects.push(n); }
    const locIn = present(f, locs, 'loc:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => locationRefs[n]);
    if (locIn.length) { refs.push({ id: locationRefs[locIn[0]], role: 'place', name: locIn[0] }); used.location = locIn[0]; }
    // The previous frame, last, palette only — and only when there is room.
    if (a.prevId && refs.length < 5 && !refs.some((r) => r.id === a.prevId)) { refs.push({ id: a.prevId, role: 'palette', name: '' }); used.palette = true; }
    // The sentence names the references BY POSITION, so it is built from the
    // list rather than assumed.
    const parts = [];
    refs.forEach((r, i) => {
      const k = i + 1;
      if (r.role === 'user') parts.push('Reference image ' + k + ' is the producer\'s own photo and is GROUND TRUTH for that person: exactly the same face, hair, body and outfit.');
      else if (r.role === 'cast') parts.push('Reference image ' + k + ' is a character sheet of ' + r.name + ' shown from several angles: this person in the shot has EXACTLY that face, hair, build and wardrobe. Render ONE view of them inside the scene — never the sheet layout, never several copies, never the neutral backdrop.');
      else if (r.role === 'object') parts.push('Reference image ' + k + ' is a reference sheet of ' + r.name + ': the same object in the shot has exactly that design, colours, markings and materials — one instance, placed in the scene.');
      else if (r.role === 'place') parts.push('Reference image ' + k + ' is the PLACE (' + r.name + '): the same architecture, layout, landmarks, materials and the same arrangement of what stands where. Light, weather and time of day follow the text, not the plate; the plate is empty of people and its framing is not this shot\'s framing.');
      else if (r.role === 'palette') parts.push('The LAST reference image is only for colour palette and film look, never for layout and never for who or where anyone is.');
    });
    let prompt = a.prompt;
    if (parts.length) {
      prompt = parts.join(' ') + ' Compose the shot described here, which may place its subjects at any distance, angle or part of the location: ' + a.prompt;
      if (a.strict) prompt = 'STRICT MATCH — the previous attempt drifted from the references (' + String(a.strictNotes || 'identity or place did not match') + '). Wherever the text and the references disagree about how a person, object or place LOOKS, the references win. ' + prompt;
    }
    return { refs, used, prompt };
  }
  function apply(body, planned) {
    planned.refs.forEach((r, i) => { body['reference_' + (i + 1)] = r.id; });
    body.prompt = planned.prompt;
    return body;
  }
  return { norm, plan, apply, tagged };
})();
// ---------------------------------------------------------------------------
const planned = CONS.plan({ f: f, opts: opts, bible: bible, prompt: prompt, prevId: prevId, userRefId: userRefId, isFirstScene: isFirstScene, afterRefusal: afterRefusal, strict: strict, strictNotes: strictNotes });
// count: 1 is mandatory — the API DEFAULTS TO FOUR images. captchaRetry: 1
// because useapi's five captcha retries per request are pure spend while
// Google throttles the account; our own cooldown loop handles that.
const body = CONS.apply({ email: rb.Flow_Email || 'fermafabiz@gmail.com', model: MODEL, prompt: prompt, aspectRatio: aspect, count: 1, captchaRetry: 1 }, planned);
console.log('IMG refs for ' + $json.id + ': ' + (planned.refs.map((r) => r.role + (r.name ? '=' + r.name : '')).join(', ') || 'none') + (strict ? ' [STRICT]' : ''));
return [{ json: { sceneId: $json.id, requestBody: body, refs: planned.refs, used: planned.used, usedReference: planned.refs.length ? planned.refs[0].id : null, castUsed: planned.used.cast, userRefApplied: planned.used.user, strict: strict, rawPrompt: prompt, promptSimilarityToPrev: Number(promptSim.toFixed(2)) } }];

// ---------------------------------------------------------------------------
// REFERENCE ASSEMBLY — shared word for word by Build Image Request (batch),
// Evaluate Image Approval (the gate's regen) and IR Build Request (the site's
